import os
import json

# شبیه‌سازی محیط مULTIPLE
envs = {
    'dev': {'DEBUG': 'True', 'DB': 'sqlite'},
    'prod': {'DEBUG': 'False', 'DB': 'postgresql'},
    'test': {'DEBUG': 'True', 'DB': 'sqlite'}
}

def create_env_file(env_name, config):
    lines = []
    for key, value in sorted(config.items()):
        lines.append(f'{key}={value}')
    return '\n'.join(lines)

# ساخت فایل‌ها
for name, config in envs.items():
    content = create_env_file(name, config)
    print(f'=== {name}.env ===')
    print(content)
    print()
